string string_xor(string a,string b){
    string output="";
    int len = min(a.size(), b.size());
    for (int i=0;i<len;i++)
    {
        if (a[i]== b[i]) 
        {
            output+='1';
        }  
        else output+='0';
    }
    // Handle cases where one string is longer than the other
    while (i < a.size()) {
        output += a[i++];
    }
    while (i < b.size()) {
        output += b[i++];
    }
    return output;
}
