vector<int> factorize(int n){
    vector<int> out={};
    for (int i=2;i*i<=n;i++)
        while (n%i==0)
        {
            n=n/i;
            out.push_back(i);
        }
    if (n!=1)
        out.push_back(n);
    return out;
