int largest_prime_factor(int n){
    if(n <= 1)
        return -1; // Return -1 if input is less than or equal to 1

    int factor = 2;

    while(factor * factor <= n){
        while(n % factor == 0){
            n /= factor;
        }
        factor++;
    }

    if(n > 1)
        return n; // If n is greater than 1 after the loop, it's a prime number

    return -1; // Return -1 if no prime factors were found
}
