        return 1;
    else{
        int ff[100];
        ff[0]=0;
        ff[1]=1;
        ff[2]=2;
        for (int i=3;i<=n;i++)
            ff[i]=ff[i-1]+ff[i-2]+ff[i-3];
        return ff[n];
    }
}

