    if (x<grid.size()-1 and grid[x+1][y]<min) min=grid[x][y];
    if (y>0 and grid[x][y-1]<min) min=grid[x][y];
    if (y<grid.size()-1 and grid[x][y+1]<min) min=grid[x][y];
    vector<int> out={};
    for (i=0;i<k;i++)
    if (i%2==0) out.push_back(1);
    else out.push_back(min);
    return out;
